using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A ladder of branches comparing one value with numbers in turn, one rung of which alone differs from the others in whether its
/// own number goes with it: a grade ladder of mark &gt;= 70, &gt;= 60 and &gt;= 50 whose last rung is mark &gt; 40, in each of the
/// twenty languages whose chains are read - with the change that makes it like the others - the same the other way round, and
/// the ladders left alone: every rung alike, mark &gt; 39 among them, two rungs, two of each, two names, numbers with no step.
/// </summary>
public class BoundaryOddOneOutTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private List<LogicFinding> Scan(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code.ReplaceLineEndings("\n"));
        return LogicPatterns.Scan(SourceFile.Read(path)!).Where(finding => finding.PatternId.EndsWith("boundary-odd-one-out", StringComparison.Ordinal)).ToList();
    }

