    [Theory]
    [MemberData(nameof(Ladders))]
    public void ARungWhoseOwnNumberGoesTheOtherWayIsFoundWithTheChangeThatMakesItLikeTheOthers(string fileName, string check, string code, int line, string message, string changedLine)
    {
        var finding = Assert.Single(Scan(fileName, code));

        Assert.Equal((check, line, message), (finding.PatternId, finding.Line, finding.Message));
        Assert.Equal((line, 1), (finding.Fix!.StartLine, finding.Fix.RemoveCount));
        Assert.Equal([changedLine], finding.Fix.NewLines);
    }

    /// <summary>A ladder of &gt; with one rung of &gt;= - 70 taken in where 90, 80 and 60 are left to the next rung - and a rising one with no step.</summary>
    [Fact]
    public void ARungThatTakesItsNumberInAmongOnesThatDoNotIsFoundAndNumbersWithNoStepAreLeftAlone()
    {
        var finding = Assert.Single(Scan("other_ways.py", "def band(score):\n    if score > 90:\n        return 1\n    elif score > 80:\n        return 2\n    elif score >= 70:\n        return 3\n    elif score > 60:\n        return 4\n    return 5\n\n\ndef life_stage(age):\n    if age < 13:\n        return \"child\"\n    elif age < 20:\n        return \"teen\"\n    elif age <= 65:\n        return \"adult\"\n    elif age < 100:\n        return \"older\"\n    return \"centenarian\"\n\n\nprint(band(70), life_stage(65))\n"));

        Assert.Equal(("logic-python-boundary-odd-one-out", 6, "Every other branch of this chain leaves its own number to the branch after it - score > 90, score > 80, score > 60 - but score >= 70 takes 70 in: score = 70 is given this branch's answer, where 90, 80 and 60 are each given the next branch's. If 70 belongs as the others' numbers do, write score > 70"), (finding.PatternId, finding.Line, finding.Message));
        Assert.Equal(["    elif score > 70:"], finding.Fix!.NewLines);
    }

    /// <summary>
    /// Every rung alike; mark &gt; 39 among &gt;= 70, 60 and 50, which is mark &gt;= 40 for whole marks; two rungs only; two of each
    /// way; rungs comparing two names; and a ladder of &lt; alike.
    /// </summary>
    [Fact]
    public void LaddersWithNoRungAloneDifferentAreLeftAlone() => Assert.Empty(Scan("ladders.py", "def grade(mark):\n    if mark >= 70:\n        return \"A\"\n    elif mark >= 60:\n        return \"B\"\n    elif mark >= 50:\n        return \"C\"\n    elif mark >= 40:\n        return \"D\"\n    return \"F\"\n\n\ndef whole_marks(mark):\n    if mark >= 70:\n        return \"A\"\n    elif mark >= 60:\n        return \"B\"\n    elif mark >= 50:\n        return \"C\"\n    elif mark > 39:\n        return \"D\"\n    return \"F\"\n\n\ndef weather(temperature):\n    if temperature > 30:\n        return \"hot\"\n    elif temperature >= 20:\n        return \"warm\"\n    return \"cold\"\n\n\ndef half_and_half(score):\n    if score >= 90:\n        return 1\n    elif score > 80:\n        return 2\n    elif score >= 70:\n        return 3\n    elif score > 60:\n        return 4\n    return 5\n\n\ndef two_names(a, b):\n    if a >= 70:\n        return 1\n    elif b >= 60:\n        return 2\n    elif a > 50:\n        return 3\n    return 4\n\n\ndef strict_ladder(age):\n    if age < 13:\n        return \"child\"\n    elif age < 18:\n        return \"teen\"\n    elif age < 65:\n        return \"adult\"\n    return \"older\"\n\n\nprint(grade(40), whole_marks(40), weather(25), half_and_half(70), two_names(1, 2), strict_ladder(20))\n"));
}
